import { afterEach, describe, expect, it } from 'vitest';
import { JSDOM } from 'jsdom';

function installDom(html: string): Document {
  const dom = new JSDOM(html, { pretendToBeVisual: true });
  globalThis.window = dom.window as unknown as Window & typeof globalThis;
  globalThis.document = dom.window.document;
  globalThis.Event = dom.window.Event;
  globalThis.MouseEvent = dom.window.MouseEvent;
  return dom.window.document;
}

function dispatchNativeMouseSequence(target: Element): void {
  for (const type of ['mousemove', 'pointerdown', 'mousedown', 'mouseup', 'pointerup', 'click']) {
    target.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
  }
}

describe('CDP-primary click dropdown fixtures', () => {
  afterEach(() => {
    Reflect.deleteProperty(globalThis, 'window');
    Reflect.deleteProperty(globalThis, 'document');
  });

  it('captures the Radix/shadcn class of dropdowns that open on pointerdown and select on pointerup', () => {
    const document = installDom(`
      <button id="trigger" role="combobox" aria-expanded="false">Category</button>
      <div id="portal-root"></div>
      <output id="value"></output>
    `);
    const trigger = document.querySelector('#trigger') as HTMLButtonElement;
    const portal = document.querySelector('#portal-root')!;
    const value = document.querySelector('#value')!;

    trigger.addEventListener('pointerdown', () => {
      trigger.setAttribute('aria-expanded', 'true');
      portal.innerHTML = `
        <div role="listbox">
          <div id="meals" role="option">Meals</div>
        </div>
      `;
      portal.querySelector('#meals')!.addEventListener('pointerup', () => {
        value.textContent = 'Meals';
        trigger.textContent = 'Meals';
        trigger.setAttribute('aria-expanded', 'false');
      });
    });

    // Baseline: DOM el.click() dispatches click only. This is the old OpenCLI
    // failure mode: the command reports success but the dropdown never opens.
    trigger.click();
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
    expect(portal.querySelector('[role="option"]')).toBeNull();
    expect(value.textContent).toBe('');

    // CDP-style mouse input opens the portal and can commit the option.
    dispatchNativeMouseSequence(trigger);
    const option = portal.querySelector('#meals')!;
    expect(trigger.getAttribute('aria-expanded')).toBe('true');

    dispatchNativeMouseSequence(option);
    expect(value.textContent).toBe('Meals');
    expect(trigger.textContent).toBe('Meals');
  });

  it('captures the MUI autocomplete class that opens on mousedown and commits on mousedown in a popper', () => {
    const document = installDom(`
      <label for="category">Category</label>
      <input id="category" role="combobox" value="" />
      <div id="mui-popper"></div>
      <output id="value"></output>
    `);
    const input = document.querySelector('#category') as HTMLInputElement;
    const popper = document.querySelector('#mui-popper')!;
    const value = document.querySelector('#value')!;

    input.addEventListener('mousedown', () => {
      popper.innerHTML = `
        <ul role="listbox">
          <li id="travel" role="option">Travel</li>
        </ul>
      `;
      popper.querySelector('#travel')!.addEventListener('mousedown', () => {
        input.value = 'Travel';
        value.textContent = 'Travel';
      });
    });

    input.click();
    expect(popper.querySelector('[role="option"]')).toBeNull();
    expect(input.value).toBe('');

    dispatchNativeMouseSequence(input);
    const option = popper.querySelector('#travel')!;
    dispatchNativeMouseSequence(option);

    expect(input.value).toBe('Travel');
    expect(value.textContent).toBe('Travel');
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const { MockWebSocket } = vi.hoisted(() => {
  class MockWebSocket {
    static OPEN = 1;
    static lastInstance: MockWebSocket | undefined;
    readyState = 1;
    private handlers = new Map<string, Array<(...args: unknown[]) => void>>();

    constructor(_url: string) {
      MockWebSocket.lastInstance = this;
      queueMicrotask(() => this.emit('open'));
    }

    on(event: string, handler: (...args: unknown[]) => void): void {
      const handlers = this.handlers.get(event) ?? [];
      handlers.push(handler);
      this.handlers.set(event, handlers);
    }

    send(_message: string): void {}

    close(): void {
      this.readyState = 3;
    }

    emit(event: string, ...args: unknown[]): void {
      for (const handler of this.handlers.get(event) ?? []) {
        handler(...args);
      }
    }
  }

  return { MockWebSocket };
});

vi.mock('ws', () => ({
  WebSocket: MockWebSocket,
}));

import { CDPBridge, CDP_REQUEST_BODY_CAPTURE_LIMIT } from './cdp.js';

describe('CDPBridge cookies', () => {
  beforeEach(() => {
    vi.unstubAllEnvs();
  });

  it('filters cookies by actual domain match instead of substring match', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');

    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue({
      cookies: [
        { name: 'good', value: '1', domain: '.example.com' },
        { name: 'exact', value: '2', domain: 'example.com' },
        { name: 'child', value: '4', domain: 'account.example.com' },
        { name: 'bad', value: '3', domain: 'notexample.com' },
      ],
    });

    const page = await bridge.connect();
    const cookies = await page.getCookies({ domain: 'example.com' });

    expect(bridge.send).toHaveBeenCalledWith('Storage.getCookies', {});
    expect(cookies).toEqual([
      { name: 'good', value: '1', domain: '.example.com' },
      { name: 'exact', value: '2', domain: 'example.com' },
      { name: 'child', value: '4', domain: 'account.example.com' },
    ]);
  });

  it.each([{}, { cookies: null }, { cookies: [null] }])('rejects malformed cookie responses %j', async result => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue(result);
    const page = await bridge.connect();
    await expect(page.getCookies({ domain: 'example.com' })).rejects.toMatchObject({ code: 'COMMAND_EXEC' });
    await bridge.close();
  });

  it('matches Chrome domain filtering rather than URL applicability', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue({ cookies: [
      { name: 'parent', value: '1', domain: '.example.com' },
      { name: 'exact', value: '2', domain: 'account.example.com' },
      { name: 'child', value: '3', domain: 'secure.account.example.com' },
    ] });
    const page = await bridge.connect();
    expect((await page.getCookies({ domain: 'account.example.com' })).map(c => c.name)).toEqual(['exact', 'child']);
    await bridge.close();
  });

  it('retains URL/path scoping for URL cookie queries', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue({ cookies: [] });
    const page = await bridge.connect();
    await page.getCookies({ url: 'https://example.com/account' });
    expect(bridge.send).toHaveBeenCalledWith('Network.getCookies', { urls: ['https://example.com/account'] });
    await bridge.close();
  });

  it('exposes native input helpers on direct CDP pages', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');

    const bridge = new CDPBridge();
    const send = vi.spyOn(bridge, 'send').mockResolvedValue({ result: { value: 'visible' } });

    const page = await bridge.connect();
    send.mockClear();

    expect(page.nativeType).toBeTypeOf('function');
    expect(page.nativeKeyPress).toBeTypeOf('function');
    expect(page.nativeClick).toBeTypeOf('function');
    expect(page.handleJavaScriptDialog).toBeTypeOf('function');
    expect(page.cdp).toBeTypeOf('function');

    await page.nativeType!('hello');
    await page.nativeKeyPress!('a', ['Ctrl']);
    await page.nativeClick!(10, 20);
    await page.handleJavaScriptDialog!(true, 'ok');
    await page.cdp!('Page.getLayoutMetrics', {});

    expect(send.mock.calls.filter(([method]) => method !== 'Runtime.evaluate')).toEqual([
      ['Input.insertText', { text: 'hello' }],
      ['Input.dispatchKeyEvent', { type: 'keyDown', key: 'a', modifiers: 2 }],
      ['Input.dispatchKeyEvent', { type: 'keyUp', key: 'a', modifiers: 2 }],
      ['Input.dispatchMouseEvent', { type: 'mouseMoved', x: 10, y: 20 }],
      ['Input.dispatchMouseEvent', { type: 'mousePressed', x: 10, y: 20, button: 'left', clickCount: 1 }],
      ['Input.dispatchMouseEvent', { type: 'mouseReleased', x: 10, y: 20, button: 'left', clickCount: 1 }],
      ['Page.handleJavaScriptDialog', { accept: true, promptText: 'ok' }],
      ['Page.getLayoutMetrics', {}],
    ]);
  });

  it.each(['hidden', 'prerender', undefined])('blocks native input when visibility is %s', async visibility => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    const send = vi.spyOn(bridge, 'send').mockResolvedValue({ result: { value: visibility } });
    const page = await bridge.connect();
    send.mockClear();
    await expect(page.nativeClick!(10, 20)).rejects.toMatchObject({ code: 'COMMAND_EXEC' });
    await expect(page.nativeKeyPress!('Enter')).rejects.toMatchObject({ code: 'COMMAND_EXEC' });
    await expect(page.pressKey('Enter')).rejects.toMatchObject({ code: 'COMMAND_EXEC' });
    expect(send.mock.calls.every(([method]) => method === 'Runtime.evaluate')).toBe(true);
    await bridge.close();
  });

  it('captures request headers and bounded post data on direct CDP pages', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');

    const bridge = new CDPBridge();
    const fullBody = 'x'.repeat(CDP_REQUEST_BODY_CAPTURE_LIMIT + 5);
    vi.spyOn(bridge, 'send').mockImplementation(async (method: string) => {
      if (method === 'Network.getRequestPostData') return { postData: fullBody };
      return {};
    });

    const page = await bridge.connect();
    await page.startNetworkCapture?.();
    MockWebSocket.lastInstance?.emit('message', Buffer.from(JSON.stringify({
      method: 'Network.requestWillBeSent',
      params: {
        requestId: 'request-1',
        request: {
          method: 'POST',
          url: 'https://example.test/rsc-action/actions/pagination',
          headers: { Authorization: 'Bearer secret', 'Content-Type': 'application/json' },
          hasPostData: true,
        },
      },
    })));

    const entries = await page.readNetworkCapture?.() as Array<Record<string, unknown>>;
    expect(entries).toHaveLength(1);
    expect(entries[0]).toMatchObject({
      method: 'POST',
      requestHeaders: { Authorization: 'Bearer secret', 'Content-Type': 'application/json' },
      requestBodyKind: 'string',
      requestBodyFullSize: fullBody.length,
      requestBodyTruncated: true,
    });
    expect(String(entries[0].requestBodyPreview)).toHaveLength(CDP_REQUEST_BODY_CAPTURE_LIMIT);
  });

  it('retains one redirect chain and drains it after the final response', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue({ body: 'final answer', base64Encoded: false });
    const page = await bridge.connect();
    await page.startNetworkCapture?.('api.example');
    const fire = (method: string, params: unknown) => MockWebSocket.lastInstance?.emit('message',
      Buffer.from(JSON.stringify({ method, params })));
    fire('Network.requestWillBeSent', { requestId: 'redirect', request: {
      method: 'POST', url: 'https://api.example/start', hasPostData: true, postData: 'original payload',
    } });
    await page.readNetworkCapture?.({ retainIncomplete: true });
    fire('Network.requestWillBeSent', { requestId: 'redirect', redirectResponse: { status: 302 }, request: {
      method: 'GET', url: 'https://api.example/finish',
    } });
    fire('Network.responseReceived', { requestId: 'redirect', response: { status: 200 } });
    fire('Network.loadingFinished', { requestId: 'redirect' });
    await new Promise(resolve => setTimeout(resolve, 0));
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([
      expect.objectContaining({ requestId: 'redirect', method: 'POST', requestBodyPreview: 'original payload',
        responsePreview: 'final answer', captureComplete: true }),
    ]);
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([]);
  });

  it('reindexes remaining requests after a completed entry is drained', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockResolvedValue({ body: 'body', base64Encoded: false });
    const page = await bridge.connect();
    await page.startNetworkCapture?.('api.example');
    const fire = (method: string, params: unknown) => MockWebSocket.lastInstance?.emit('message',
      Buffer.from(JSON.stringify({ method, params })));
    for (const requestId of ['done', 'pending']) {
      fire('Network.requestWillBeSent', { requestId, request: { method: 'GET', url: 'https://api.example/' + requestId } });
    }
    fire('Network.loadingFailed', { requestId: 'done' });
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toHaveLength(2);
    fire('Network.responseReceived', { requestId: 'pending', response: { status: 201 } });
    fire('Network.loadingFinished', { requestId: 'pending' });
    await new Promise(resolve => setTimeout(resolve, 0));
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([
      expect.objectContaining({ requestId: 'pending', responseStatus: 201, responsePreview: 'body', captureComplete: true }),
    ]);
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([]);
  });

  it('retains an early-read request until the delayed response body completes', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    let releaseBody!: (value: unknown) => void;
    const body = new Promise(resolve => { releaseBody = resolve; });
    vi.spyOn(bridge, 'send').mockImplementation(async (method: string) =>
      method === 'Network.getResponseBody' ? body : {});
    const page = await bridge.connect();
    await page.startNetworkCapture?.('api.example');
    const fire = (method: string, params: unknown) => MockWebSocket.lastInstance?.emit('message',
      Buffer.from(JSON.stringify({ method, params })));
    fire('Network.requestWillBeSent', { requestId: 'r2', request: { method: 'POST', url: 'https://api.example/gen', postData: '{}', hasPostData: true } });
    const early = await page.readNetworkCapture?.({ retainIncomplete: true }) as Array<Record<string, unknown>>;
    expect(early[0].responsePreview).toBeUndefined();
    fire('Network.responseReceived', { requestId: 'r2', response: { status: 200 } });
    fire('Network.loadingFinished', { requestId: 'r2' });
    releaseBody({ body: '{"clips":[]}', base64Encoded: false });
    await new Promise(resolve => setTimeout(resolve, 0));
    const completed = await page.readNetworkCapture?.({ retainIncomplete: true }) as Array<Record<string, unknown>>;
    expect(completed[0]).toMatchObject({ responseStatus: 200, responsePreview: '{"clips":[]}', captureComplete: true });
    expect(completed[0].requestId).toBe('r2');
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([]);
  });

  it('does not complete a capture before its delayed request post data arrives', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    let releasePostData!: (value: unknown) => void;
    const postData = new Promise(resolve => { releasePostData = resolve; });
    vi.spyOn(bridge, 'send').mockImplementation(async (method: string) =>
      method === 'Network.getRequestPostData' ? postData : { body: '{"ok":1}', base64Encoded: false });
    const page = await bridge.connect();
    await page.startNetworkCapture?.('api.example');
    const fire = (method: string, params: unknown) => MockWebSocket.lastInstance?.emit('message',
      Buffer.from(JSON.stringify({ method, params })));
    fire('Network.requestWillBeSent', { requestId: 'r3', request: { method: 'POST', url: 'https://api.example/gen', hasPostData: true } });
    fire('Network.responseReceived', { requestId: 'r3', response: { status: 200 } });
    fire('Network.loadingFinished', { requestId: 'r3' });
    await new Promise(resolve => setTimeout(resolve, 0));
    // Response body is settled, but the request body fetch has not landed:
    // the entry must stay incomplete so a retaining read keeps it.
    const beforePostData = await page.readNetworkCapture?.({ retainIncomplete: true }) as Array<Record<string, unknown>>;
    expect(beforePostData[0].responsePreview).toBe('{"ok":1}');
    expect(beforePostData[0].captureComplete).toBe(false);
    releasePostData({ postData: '{"mv":"v6"}' });
    await new Promise(resolve => setTimeout(resolve, 0));
    const complete = await page.readNetworkCapture?.({ retainIncomplete: true }) as Array<Record<string, unknown>>;
    expect(complete[0]).toMatchObject({ requestBodyPreview: '{"mv":"v6"}', captureComplete: true });
    expect(await page.readNetworkCapture?.({ retainIncomplete: true })).toEqual([]);
  });

  it('returns a retaining snapshot without waiting on a stalled response body fetch', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    vi.spyOn(bridge, 'send').mockImplementation(async (method: string) =>
      method === 'Network.getResponseBody' ? new Promise(() => {}) : {});
    const page = await bridge.connect();
    await page.startNetworkCapture?.('api.example');
    const fire = (method: string, params: unknown) => MockWebSocket.lastInstance?.emit('message',
      Buffer.from(JSON.stringify({ method, params })));
    fire('Network.requestWillBeSent', { requestId: 'r4', request: { method: 'POST', url: 'https://api.example/gen', postData: '{}', hasPostData: true } });
    fire('Network.responseReceived', { requestId: 'r4', response: { status: 200 } });
    fire('Network.loadingFinished', { requestId: 'r4' });
    const reading = page.readNetworkCapture?.({ retainIncomplete: true }) as Promise<Array<Record<string, unknown>>>;
    const snapshot = await Promise.race([
      reading,
      new Promise((_, reject) => setTimeout(() => reject(new Error('retaining read blocked on a stalled body fetch')), 50)),
    ]) as Array<Record<string, unknown>>;
    expect(snapshot[0]).toMatchObject({ requestId: 'r4', responseStatus: 200 });
    expect(snapshot[0].responsePreview).toBeUndefined();
  });
});

describe('CDPBridge init script', () => {
  const tempDirs: string[] = [];
  afterEach(() => {
    vi.unstubAllEnvs();
    for (const dir of tempDirs.splice(0)) rmSync(dir, { recursive: true, force: true });
  });
  beforeEach(() => {
    vi.unstubAllEnvs();
  });

  const initScripts = (calls: unknown[][]) => calls
    .filter(([method]) => method === 'Page.addScriptToEvaluateOnNewDocument')
    .map(([, params]) => (params as { source: string }).source);

  it('registers OPENCLI_CDP_INIT_SCRIPT after the stealth script', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const dir = mkdtempSync(join(tmpdir(), 'opencli-init-'));
    tempDirs.push(dir);
    const file = join(dir, 'init.js');
    writeFileSync(file, 'window.__opencliInit = 1;');
    vi.stubEnv('OPENCLI_CDP_INIT_SCRIPT', file);

    const bridge = new CDPBridge();
    const send = vi.spyOn(bridge, 'send').mockResolvedValue({});
    await bridge.connect();

    const sources = initScripts(send.mock.calls);
    expect(sources).toHaveLength(2);
    expect(sources[1]).toBe('window.__opencliInit = 1;');
    await bridge.close();
  });

  it.skipIf(process.platform === 'win32')('rejects a FIFO before opening a CDP connection', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'opencli-init-'));
    tempDirs.push(dir);
    const file = join(dir, 'init.pipe');
    execFileSync('mkfifo', [file]);
    vi.stubEnv('OPENCLI_CDP_INIT_SCRIPT', file);
    const previousSocket = MockWebSocket.lastInstance;
    await expect(new CDPBridge().connect({ cdpEndpoint: 'ws://127.0.0.1:9222' }))
      .rejects.toThrow('regular JavaScript file');
    expect(MockWebSocket.lastInstance).toBe(previousSocket);
  });

  it('registers only the stealth script when unset', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');

    const bridge = new CDPBridge();
    const send = vi.spyOn(bridge, 'send').mockResolvedValue({});
    await bridge.connect();

    expect(initScripts(send.mock.calls)).toHaveLength(1);
    await bridge.close();
  });
});

describe('CDPPage.evaluateOnce', () => {
  it('does not resend Runtime.evaluate after a target navigation', async () => {
    vi.stubEnv('OPENCLI_CDP_ENDPOINT', 'ws://127.0.0.1:9222/devtools/page/1');
    const bridge = new CDPBridge();
    const send = vi.spyOn(bridge, 'send').mockResolvedValue({});
    const page = await bridge.connect();
    send.mockClear();
    const error = new Error('Inspected target navigated or closed');
    send.mockRejectedValue(error);
    await expect(page.evaluateOnce!('publishComment()')).rejects.toBe(error);
    expect(send).toHaveBeenCalledTimes(1);
    await bridge.close();
    vi.unstubAllEnvs();
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import {
    DEFAULT_TTL_MS,
    findEntry,
    getCachePath,
    loadNetworkCache,
    saveNetworkCache,
    type CachedNetworkEntry,
    type NetworkCacheFile,
} from './network-cache.js';

function makeEntry(key: string, body: unknown = { ok: true }): CachedNetworkEntry {
    return { key, url: `https://x.com/${key}`, method: 'GET', status: 200, size: 2, ct: 'application/json', body };
}

describe('network-cache', () => {
    let baseDir: string;

    beforeEach(() => {
        baseDir = fs.mkdtempSync(path.join(os.tmpdir(), 'opencli-netcache-'));
    });
    afterEach(() => {
        fs.rmSync(baseDir, { recursive: true, force: true });
    });

    it('sanitizes session names into safe filenames', () => {
        const p = getCachePath('twitter/agent 1', baseDir);
        expect(path.basename(p)).toBe('twitter_agent_1.json');
    });

    it('round-trips entries through save + load', () => {
        saveNetworkCache('ws', [makeEntry('UserTweets'), makeEntry('UserByScreenName')], baseDir);
        const res = loadNetworkCache('ws', { baseDir });
        expect(res.status).toBe('ok');
        expect(res.file?.entries).toHaveLength(2);
        expect(res.file?.entries[0].key).toBe('UserTweets');
    });

    it('reports missing when cache file does not exist', () => {
        expect(loadNetworkCache('nope', { baseDir }).status).toBe('missing');
    });

    it('reports expired when the cache is older than ttl', () => {
        saveNetworkCache('ws', [makeEntry('A')], baseDir);
        const future = Date.now() + DEFAULT_TTL_MS + 60_000;
        const res = loadNetworkCache('ws', { baseDir, now: future });
        expect(res.status).toBe('expired');
        expect(res.file?.entries).toHaveLength(1);
    });

    it('reports corrupt for malformed json', () => {
        const file = getCachePath('ws', baseDir);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, '{not json');
        expect(loadNetworkCache('ws', { baseDir }).status).toBe('corrupt');
    });

    it('reports corrupt for wrong schema version', () => {
        const file = getCachePath('ws', baseDir);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, JSON.stringify({ version: 0, entries: [] }));
        expect(loadNetworkCache('ws', { baseDir }).status).toBe('corrupt');
    });

    it('findEntry returns matching entry or null', () => {
        const file: NetworkCacheFile = {
            version: 1, session: 'ws', savedAt: new Date().toISOString(),
            entries: [makeEntry('A'), makeEntry('B')],
        };
        expect(findEntry(file, 'B')?.key).toBe('B');
        expect(findEntry(file, 'missing')).toBeNull();
    });

    it.skipIf(process.platform === 'win32')('writes the cache file with 0o600 owner-only permissions', () => {
        saveNetworkCache('ws', [makeEntry('UserTweets')], baseDir);
        const target = getCachePath('ws', baseDir);
        const mode = fs.statSync(target).mode & 0o777;
        expect(mode).toBe(0o600);
    });

    it.skipIf(process.platform === 'win32')('tightens an existing cache file before rewriting it', () => {
        const target = getCachePath('ws', baseDir);
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.writeFileSync(target, '{"version":1,"session":"ws","savedAt":"old","entries":[]}', { mode: 0o644 });

        saveNetworkCache('ws', [makeEntry('UserTweets')], baseDir);

        const mode = fs.statSync(target).mode & 0o777;
        expect(mode).toBe(0o600);
        const reloaded = loadNetworkCache('ws', { baseDir });
        expect(reloaded.status).toBe('ok');
        expect(reloaded.file?.entries[0].key).toBe('UserTweets');
    });
});

import { cli, Strategy } from '@jackwener/opencli/registry';
import { ArgumentError } from '@jackwener/opencli/errors';
import {
    callGateway,
    emptyResult,
    formatRating,
    makeDeepLink,
    requirePositiveInt,
    requireText,
    truncate,
} from './utils.js';

/**
 * Search scope mapping — mirrors the official SKILL.md "scope 对应关系" table.
 * Keys are user-facing aliases; values are the int the gateway expects.
 */
export const SEARCH_SCOPES = Object.freeze({
    all: 0,
    ebook: 10,
    webnovel: 16,
    audio: 14,
    author: 6,
    fulltext: 12,
    booklist: 13,
    mp: 2,
    article: 4,
});

const SCOPE_LABEL = Object.freeze({
    0: '全部',
    10: '电子书',
    16: '网文小说',
    14: '微信听书',
    6: '作者',
    12: '全文',
    13: '书单',
    2: '公众号',
    4: '文章',
});

cli({
    site: 'weread-official',
    name: 'search',
    access: 'read',
    description: 'Search WeRead store via the official agent gateway',
    domain: 'weread.qq.com',
    strategy: Strategy.PUBLIC,
    browser: false,
    args: [
        { name: 'keyword', positional: true, required: true, help: 'Search keyword' },
        { name: 'scope', default: 'ebook', choices: Object.keys(SEARCH_SCOPES), help: 'Search type (all/ebook/webnovel/audio/author/fulltext/booklist/mp/article)' },
        { name: 'count', type: 'int', help: 'Page size (gateway default 15 when omitted)' },
        { name: 'max-idx', type: 'int', default: 0, help: 'Pagination offset, use searchIdx of last item from previous page' },
    ],
    columns: ['rank', 'scope', 'bookId', 'title', 'author', 'rating', 'readingCount', 'category', 'searchIdx', 'cover', 'intro', 'link'],
    func: async (args) => {
        const keyword = requireText(args.keyword, 'keyword');
        const scopeKey = String(args.scope ?? 'ebook').trim();
        if (!Object.prototype.hasOwnProperty.call(SEARCH_SCOPES, scopeKey)) {
            throw new ArgumentError(
                `weread-official: scope must be one of: ${Object.keys(SEARCH_SCOPES).join(', ')}`,
            );
        }
        const scope = SEARCH_SCOPES[scopeKey];
        const params = { keyword, scope, maxIdx: args['max-idx'] ?? 0 };
        if (args.count !== undefined && args.count !== null && args.count !== '') {
            params.count = requirePositiveInt(args.count, 'count', { max: 100 });
        }

        const payload = await callGateway('/store/search', params);
        const groups = Array.isArray(payload?.results) ? payload.results : [];
        if (groups.length === 0) {
            emptyResult('search', `No results for "${keyword}" (scope=${scopeKey}).`);
        }

        const rows = [];
        let rank = 0;
        for (const group of groups) {
            const groupScope = SCOPE_LABEL[Number(group?.scope)] ?? '';
            const books = Array.isArray(group?.books) ? group.books : [];
            for (const entry of books) {
                rank += 1;
                const info = entry?.bookInfo ?? {};
                const bookId = String(info.bookId ?? '').trim();
                rows.push({
                    rank,
                    scope: groupScope,
                    bookId,
                    title: String(info.title ?? ''),
                    author: String(info.author ?? ''),
                    rating: formatRating(entry?.newRating),
                    readingCount: Number(entry?.readingCount ?? 0),
                    category: String(info.category ?? ''),
                    searchIdx: Number(entry?.searchIdx ?? 0),
                    cover: String(info.cover ?? ''),
                    intro: truncate(info.intro, 120),
                    link: bookId ? makeDeepLink({ bookId }) : '',
                });
            }
        }
        if (rows.length === 0) {
            emptyResult('search', `No books found in results for "${keyword}" (scope=${scopeKey}).`);
        }
        return rows;
    },
});

import { cli, Strategy } from '@jackwener/opencli/registry';
import { callGateway, emptyResult, SKILL_VERSION } from './utils.js';

/**
 * `/_list` is the gateway's meta-endpoint. The response shape is not strongly
 * specified in SKILL.md beyond "returns all available api_name + their param
 * definitions", so we surface every visible field with light normalization
 * (api_name + description/help + required/optional params, falling back to a
 * raw-JSON column when the gateway changes shape).
 *
 * `clientSkillVersion` row is appended so debug output makes the local
 * SKILL_VERSION explicit — useful when triaging upgrade_info mismatches.
 */
cli({
    site: 'weread-official',
    name: 'list-apis',
    access: 'read',
    description: 'List every api_name supported by the WeRead agent gateway',
    domain: 'weread.qq.com',
    strategy: Strategy.PUBLIC,
    browser: false,
    args: [],
    columns: ['rank', 'apiName', 'description', 'required', 'optional', 'extras'],
    func: async () => {
        const payload = await callGateway('/_list', {});
        const apis = extractApiList(payload);
        if (apis.length === 0) {
            emptyResult('list-apis', 'Gateway returned no api inventory.');
        }
        const rows = apis.map((entry, i) => {
            const required = formatParamList(entry?.required ?? entry?.requiredParams ?? entry?.params?.required);
            const optional = formatParamList(entry?.optional ?? entry?.optionalParams ?? entry?.params?.optional);
            const description = String(entry?.description ?? entry?.help ?? entry?.summary ?? '');
            const extras = summarizeExtras(entry, ['api_name', 'apiName', 'name', 'description', 'help', 'summary', 'required', 'optional', 'requiredParams', 'optionalParams', 'params']);
            return {
                rank: i + 1,
                apiName: String(entry?.api_name ?? entry?.apiName ?? entry?.name ?? ''),
                description,
                required,
                optional,
                extras,
            };
        });
        rows.push({
            rank: rows.length + 1,
            apiName: '(client)',
            description: 'Local skill version reported with every gateway request',
            required: '',
            optional: '',
            extras: `SKILL_VERSION=${SKILL_VERSION}`,
        });
        return rows;
    },
});

function extractApiList(payload) {
    if (!payload || typeof payload !== 'object') return [];
    const candidates = [payload?.apis, payload?.list, payload?.data, payload?.items, payload?.endpoints];
    for (const candidate of candidates) {
        if (Array.isArray(candidate) && candidate.length > 0) return candidate;
    }
    if (Array.isArray(payload)) return payload;
    return [];
}

function formatParamList(value) {
    if (!value) return '';
    if (Array.isArray(value)) {
        return value
            .map((entry) => (typeof entry === 'string' ? entry : entry?.name ?? entry?.param ?? ''))
            .filter(Boolean)
            .join(', ');
    }
    if (typeof value === 'object') {
        return Object.keys(value).filter(Boolean).join(', ');
    }
    return String(value);
}

function summarizeExtras(entry, knownKeys) {
    if (!entry || typeof entry !== 'object') return '';
    const known = new Set(knownKeys);
    const rest = {};
    for (const [key, value] of Object.entries(entry)) {
        if (known.has(key)) continue;
        rest[key] = value;
    }
    if (Object.keys(rest).length === 0) return '';
    try {
        return JSON.stringify(rest);
    }
    catch {
        return '';
    }
}

/**
 * CDP client — implements IPage by connecting directly to a Chrome CDP WebSocket.
 *
 * Fixes applied:
 * - send() now has a 30s timeout guard (P0 #4)
 * - goto() waits for Page.loadEventFired instead of hardcoded 1s sleep (P1 #3)
 * - Implemented scroll, autoScroll, screenshot, networkRequests (P1 #2)
 * - Shared DOM helper methods extracted to reduce duplication with Page (P1 #5)
 */

import { WebSocket, type RawData } from 'ws';
import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';
import { readFileSync, statSync } from 'node:fs';
import type { BrowserCookie, BrowserEvaluateFunction, IPage, ScreenshotOptions } from '../types.js';
import type { IBrowserFactory } from '../runtime.js';
import { buildEvaluateExpression } from './utils.js';
import { generateStealthJs } from './stealth.js';
import { waitForDomStableJs } from './dom-helpers.js';
import { isRecord, saveBase64ToFile } from '../utils.js';
import { CommandExecutionError } from '../errors.js';
import { CDPBasePage } from './base-page.js';

export interface CDPTarget {
  type?: string;
  url?: string;
  title?: string;
  webSocketDebuggerUrl?: string;
}

interface RuntimeEvaluateResult {
  result?: {
    value?: unknown;
  };
  exceptionDetails?: {
    exception?: {
      description?: string;
    };
  };
}

const CDP_SEND_TIMEOUT = 30_000;

// Memory guard for in-process capture. The 4k cap we used to apply everywhere
// silently truncated JSON so `JSON.parse` failed or gave partial objects — the
// primary agent-facing bug. Now we keep the full body up to a large cap and
// surface `responseBodyFullSize` + `responseBodyTruncated` so downstream layers
// can tell the agent what happened instead of lying about the payload.
export const CDP_RESPONSE_BODY_CAPTURE_LIMIT = 8 * 1024 * 1024;
export const CDP_REQUEST_BODY_CAPTURE_LIMIT = 1 * 1024 * 1024;

export class CDPBridge implements IBrowserFactory {
  private _ws: WebSocket | null = null;
  private _idCounter = 0;
  private _pending = new Map<number, { resolve: (val: unknown) => void; reject: (err: Error) => void; timer: ReturnType<typeof setTimeout> }>();
  private _eventListeners = new Map<string, Set<(params: unknown) => void>>();

  async connect(opts?: { timeout?: number; session?: string; cdpEndpoint?: string; contextId?: string; idleTimeout?: number; windowMode?: 'foreground' | 'background'; surface?: 'browser' | 'adapter'; siteSession?: 'ephemeral' | 'persistent' }): Promise<IPage> {
    if (this._ws) throw new Error('CDPBridge is already connected. Call close() before reconnecting.');

    const endpoint = opts?.cdpEndpoint ?? process.env.OPENCLI_CDP_ENDPOINT;
    if (!endpoint) throw new Error('CDP endpoint not provided (pass cdpEndpoint or set OPENCLI_CDP_ENDPOINT)');

    // Validate before connecting: reading a FIFO synchronously could block forever.
    const initPath = process.env.OPENCLI_CDP_INIT_SCRIPT;
    if (initPath && !statSync(initPath).isFile()) {
      throw new Error('OPENCLI_CDP_INIT_SCRIPT must point to a regular JavaScript file');
    }
    const initSource = initPath ? readFileSync(initPath, 'utf8') : undefined;

    let wsUrl = endpoint;
    if (endpoint.startsWith('http')) {
      const targets = await fetchJsonDirect(`${endpoint.replace(/\/$/, '')}/json`) as CDPTarget[];
      const target = selectCDPTarget(targets);
      if (!target || !target.webSocketDebuggerUrl) {
        throw new Error('No inspectable targets found at CDP endpoint');
      }
      wsUrl = target.webSocketDebuggerUrl;
    }

    return new Promise((resolve, reject) => {
      const ws = new WebSocket(wsUrl);
      const timeoutMs = (opts?.timeout ?? 10) * 1000;
      const timeout = setTimeout(() => {
        this._ws = null;
        ws.close();
        reject(new Error('CDP connect timeout'));
      }, timeoutMs);

      ws.on('open', async () => {
        clearTimeout(timeout);
        this._ws = ws;
        try {
          await this.send('Page.enable');
          await this.send('Page.addScriptToEvaluateOnNewDocument', { source: generateStealthJs() });
          // Optional caller script for every new document, e.g. state a headless peer cannot share across connections.
          if (initSource !== undefined) await this.send('Page.addScriptToEvaluateOnNewDocument', { source: initSource });
        } catch (err) {
          ws.close();
          reject(err instanceof Error ? err : new Error(String(err)));
          return;
        }
        resolve(new CDPPage(this));
      });

      ws.on('error', (err: Error) => {
        clearTimeout(timeout);
        reject(err);
      });

      ws.on('message', (data: RawData) => {
        try {
          const msg = JSON.parse(data.toString());
          if (msg.id && this._pending.has(msg.id)) {
            const entry = this._pending.get(msg.id)!;
            clearTimeout(entry.timer);
            this._pending.delete(msg.id);
            if (msg.error) {
              entry.reject(new Error(msg.error.message));
            } else {
              entry.resolve(msg.result);
            }
          }
          if (msg.method) {
            const listeners = this._eventListeners.get(msg.method);
            if (listeners) {
              for (const fn of listeners) fn(msg.params);
            }
          }
        } catch (err) {
          if (process.env.OPENCLI_VERBOSE) {
            // eslint-disable-next-line no-console
            console.error('[cdp] Failed to parse WebSocket message:', err instanceof Error ? err.message : err);
          }
        }
      });
    });
  }

  async close(): Promise<void> {
    if (this._ws) {
      this._ws.close();
      this._ws = null;
    }
    for (const p of this._pending.values()) {
      clearTimeout(p.timer);
      p.reject(new Error('CDP connection closed'));
    }
    this._pending.clear();
    this._eventListeners.clear();
  }

  async send(method: string, params: Record<string, unknown> = {}, timeoutMs: number = CDP_SEND_TIMEOUT): Promise<unknown> {
    if (!this._ws || this._ws.readyState !== WebSocket.OPEN) {
      throw new Error('CDP connection is not open');
    }
    const id = ++this._idCounter;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this._pending.delete(id);
        reject(new Error(`CDP command '${method}' timed out after ${timeoutMs / 1000}s`));
      }, timeoutMs);
      this._pending.set(id, { resolve, reject, timer });
      this._ws!.send(JSON.stringify({ id, method, params }));
    });
  }

  on(event: string, handler: (params: unknown) => void): void {
    let set = this._eventListeners.get(event);
    if (!set) {
      set = new Set();
      this._eventListeners.set(event, set);
    }
    set.add(handler);
  }

  off(event: string, handler: (params: unknown) => void): void {
    this._eventListeners.get(event)?.delete(handler);
  }

  waitForEvent(event: string, timeoutMs: number = 15_000): Promise<unknown> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.off(event, handler);
        reject(new Error(`Timed out waiting for CDP event '${event}'`));
      }, timeoutMs);
      const handler = (params: unknown) => {
        clearTimeout(timer);
        this.off(event, handler);
        resolve(params);
      };
      this.on(event, handler);
    });
  }
}

class CDPPage extends CDPBasePage {
  private _pageEnabled = false;

  // Network capture state (mirrors extension/src/cdp.ts NetworkCaptureEntry shape)
  private _networkCapturing = false;
  private _networkCapturePattern = '';
  private _networkEntries: Array<{
    requestId: string; url: string; method: string; responseStatus?: number;
    requestHeaders?: Record<string, string>;
    requestBodyKind?: string;
    requestBodyPreview?: string;
    requestBodyFullSize?: number;
    requestBodyTruncated?: boolean;
    responseContentType?: string;
    responsePreview?: string;
    responseBodyFullSize?: number;
    responseBodyTruncated?: boolean;
    requestBodyPending?: boolean;
    responseFinished?: boolean;
    captureComplete?: boolean;
    timestamp: number;
  }> = [];
  private _pendingRequests = new Map<string, number>(); // requestId → index in _networkEntries
  private _pendingBodyFetches: Set<Promise<void>> = new Set(); // track in-flight getResponseBody calls
  private _consoleMessages: Array<{ type: string; text: string; timestamp: number }> = [];
  private _consoleCapturing = false;

  constructor(private bridge: CDPBridge) {
    super();
  }

  async goto(url: string, options?: { waitUntil?: 'load' | 'none'; settleMs?: number; allowBoundNavigation?: boolean }): Promise<void> {
    if (!this._pageEnabled) {
      await this.bridge.send('Page.enable');
      this._pageEnabled = true;
    }
    const loadPromise = this.bridge.waitForEvent('Page.loadEventFired', 30_000).catch(() => {});
    await this.bridge.send('Page.navigate', { url });
    await loadPromise;
    this._lastUrl = url;
    if (options?.waitUntil !== 'none') {
      const maxMs = options?.settleMs ?? 1000;
      await this.evaluate(waitForDomStableJs(maxMs, Math.min(500, maxMs)));
    }
  }

  async evaluate<T = unknown>(js: string): Promise<T>;
  async evaluate<Args extends unknown[], T>(fn: BrowserEvaluateFunction<Args, T>, ...args: Args): Promise<Awaited<T>>;
  async evaluate(input: string | BrowserEvaluateFunction<unknown[], unknown>, ...args: unknown[]): Promise<unknown> {
    const expression = buildEvaluateExpression(input, args);
    const result = await this.bridge.send('Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    }) as RuntimeEvaluateResult;
    if (result.exceptionDetails) {
      throw new Error('Evaluate error: ' + (result.exceptionDetails.exception?.description || 'Unknown exception'));
    }
    return result.result?.value;
  }

  /** Direct CDP evaluation has no replay/retry path. */
  async evaluateOnce<T = unknown>(js: string): Promise<T> {
    return this.evaluate<T>(js);
  }

  async getCookies(opts: { domain?: string; url?: string } = {}): Promise<BrowserCookie[]> {
    // Network.getCookies without URLs is scoped to the current page, which may
    // be on another site during a no-navigation auth check.
    const result = opts.url
      ? await this.bridge.send('Network.getCookies', { urls: [opts.url] })
      : await this.bridge.send('Storage.getCookies', {});
    if (!isRecord(result) || !Array.isArray(result.cookies) || !result.cookies.every(isCookie)) {
      throw new CommandExecutionError('CDP returned an invalid cookies response');
    }
    const cookies = result.cookies;
    const domain = opts.domain;
    return domain
      ? cookies.filter((cookie): cookie is BrowserCookie => isCookie(cookie) && matchesCookieDomain(cookie.domain, domain))
      : cookies;
  }

  async screenshot(options: ScreenshotOptions = {}): Promise<string> {
    const fullPage = options.fullPage === true;
    const overrideWidth = options.width && options.width > 0 ? Math.ceil(options.width) : undefined;
    // height is ignored under fullPage so the captureBeyondViewport path stays unchanged for users who pass --height alongside --full-page.
    const overrideHeight = !fullPage && options.height && options.height > 0 ? Math.ceil(options.height) : undefined;
    const needsOverride = overrideWidth !== undefined || overrideHeight !== undefined;

    if (needsOverride) {
      if (overrideWidth !== undefined && fullPage) {
        await this.bridge.send('Emulation.setDeviceMetricsOverride', {
          mobile: false,
          width: overrideWidth,
          height: 0,
          deviceScaleFactor: 1,
        });
      }
      let finalWidth = overrideWidth ?? 0;
      let finalHeight = overrideHeight ?? 0;
      if (fullPage) {
        const metrics = await this.bridge.send('Page.getLayoutMetrics');
        const m = isRecord(metrics) ? metrics : {};
        const css = isRecord(m.cssContentSize) ? m.cssContentSize : undefined;
        const fb = isRecord(m.contentSize) ? m.contentSize : undefined;
        const size = css ?? fb;
        if (size && typeof size.width === 'number' && typeof size.height === 'number') {
          if (finalWidth === 0) finalWidth = Math.ceil(size.width);
          finalHeight = Math.ceil(size.height);
        }
      }
      await this.bridge.send('Emulation.setDeviceMetricsOverride', {
        mobile: false,
        width: finalWidth,
        height: finalHeight,
        deviceScaleFactor: 1,
      });
    }

    try {
      const result = await this.bridge.send('Page.captureScreenshot', {
        format: options.format ?? 'png',
        quality: options.format === 'jpeg' ? (options.quality ?? 80) : undefined,
        captureBeyondViewport: !needsOverride && fullPage,
      });
      const base64 = isRecord(result) && typeof result.data === 'string' ? result.data : '';
      if (options.path) {
        await saveBase64ToFile(base64, options.path);
      }
      return base64;
    } finally {
      if (needsOverride) {
        await this.bridge.send('Emulation.clearDeviceMetricsOverride').catch(() => {});
      }
    }
  }

  async startNetworkCapture(pattern: string = ''): Promise<boolean> {
    // Always update the filter pattern
    this._networkCapturePattern = pattern;

    // Reset state only on first start; avoid wiping entries if already capturing
    if (!this._networkCapturing) {
      this._networkEntries = [];
      this._pendingRequests.clear();
      this._pendingBodyFetches.clear();
      await this.bridge.send('Network.enable');

      // Step 1: Record request method/url on requestWillBeSent
      this.bridge.on('Network.requestWillBeSent', (params: unknown) => {
        const p = params as {
          requestId: string;
          request: {
            method: string;
            url: string;
            headers?: Record<string, unknown>;
            postData?: string;
            hasPostData?: boolean;
          };
          timestamp: number;
        };
        // Redirect hops reuse the request ID. Keep the original request/body
        // and settle it from the final response instead of retaining an orphan.
        if (this._pendingRequests.has(p.requestId)) return;
        if (!this._networkCapturePattern || p.request.url.includes(this._networkCapturePattern)) {
          const rawBody = typeof p.request.postData === 'string' ? p.request.postData : '';
          const bodyTruncated = rawBody.length > CDP_REQUEST_BODY_CAPTURE_LIMIT;
          const entry: (typeof this._networkEntries)[number] = {
            requestId: p.requestId,
            url: p.request.url,
            method: p.request.method,
            requestHeaders: Object.fromEntries(
              Object.entries(p.request.headers ?? {}).map(([name, value]) => [name, String(value)]),
            ),
            requestBodyKind: p.request.hasPostData ? 'string' : 'empty',
            requestBodyPreview: bodyTruncated ? rawBody.slice(0, CDP_REQUEST_BODY_CAPTURE_LIMIT) : rawBody,
            requestBodyFullSize: rawBody.length,
            requestBodyTruncated: bodyTruncated,
            timestamp: Date.now(),
          };
          const idx = this._networkEntries.push(entry) - 1;
          this._pendingRequests.set(p.requestId, idx);

          if (p.request.hasPostData && p.request.postData === undefined) {
            // Complete only when BOTH bodies are settled; a response body that
            // finishes first must not let a retaining read drop the entry
            // before its late request body lands.
            entry.requestBodyPending = true;
            const settleComplete = () => {
              entry.captureComplete = entry.responseFinished === true && entry.requestBodyPending !== true;
            };
            const requestBodyFetch = this.bridge.send('Network.getRequestPostData', { requestId: p.requestId }).then((result: unknown) => {
              const postData = (result as { postData?: string } | undefined)?.postData;
              if (typeof postData !== 'string') return;
              const truncated = postData.length > CDP_REQUEST_BODY_CAPTURE_LIMIT;
              entry.requestBodyPreview = truncated
                ? postData.slice(0, CDP_REQUEST_BODY_CAPTURE_LIMIT)
                : postData;
              entry.requestBodyFullSize = postData.length;
              entry.requestBodyTruncated = truncated;
            }).catch(() => {
              // Some request types do not expose post data.
            }).finally(() => {
              entry.requestBodyPending = false;
              settleComplete();
              this._pendingBodyFetches.delete(requestBodyFetch);
            });
            this._pendingBodyFetches.add(requestBodyFetch);
          }
        }
      });

      // Step 2: Fill in response metadata on responseReceived
      this.bridge.on('Network.responseReceived', (params: unknown) => {
        const p = params as { requestId: string; response: { status: number; mimeType?: string } };
        const idx = this._pendingRequests.get(p.requestId);
        if (idx !== undefined) {
          this._networkEntries[idx].responseStatus = p.response.status;
          this._networkEntries[idx].responseContentType = p.response.mimeType || '';
        }
      });

      // Step 3: Fetch body on loadingFinished (body is only reliably available after this)
      this.bridge.on('Network.loadingFinished', (params: unknown) => {
        const p = params as { requestId: string };
        const idx = this._pendingRequests.get(p.requestId);
        if (idx !== undefined) {
          const entry = this._networkEntries[idx];
          const bodyFetch = this.bridge.send('Network.getResponseBody', { requestId: p.requestId }).then((result: unknown) => {
            const r = result as { body?: string; base64Encoded?: boolean } | undefined;
            if (typeof r?.body === 'string') {
              const fullSize = r.body.length;
              const truncated = fullSize > CDP_RESPONSE_BODY_CAPTURE_LIMIT;
              const body = truncated ? r.body.slice(0, CDP_RESPONSE_BODY_CAPTURE_LIMIT) : r.body;
              entry.responsePreview = r.base64Encoded ? `base64:${body}` : body;
              entry.responseBodyFullSize = fullSize;
              entry.responseBodyTruncated = truncated;
            }
          }).catch((err) => {
            // Body unavailable for some requests (e.g. uploads) — non-fatal
            if (process.env.OPENCLI_VERBOSE) {
              // eslint-disable-next-line no-console
              console.error(`[cdp] getResponseBody failed for ${p.requestId}:`, err instanceof Error ? err.message : err);
            }
          }).finally(() => {
            entry.responseFinished = true;
            entry.captureComplete = entry.requestBodyPending !== true;
            this._pendingBodyFetches.delete(bodyFetch);
          });
          this._pendingBodyFetches.add(bodyFetch);
          this._pendingRequests.delete(p.requestId);
        }
      });

      this.bridge.on('Network.loadingFailed', (params: unknown) => {
        const p = params as { requestId: string };
        const idx = this._pendingRequests.get(p.requestId);
        if (idx !== undefined) {
          const entry = this._networkEntries[idx];
          entry.responseFinished = true;
          // Mirror the extension: a pending request body still completes later.
          entry.captureComplete = entry.requestBodyPending !== true;
          this._pendingRequests.delete(p.requestId);
        }
      });

      this._networkCapturing = true;
    }
    return true;
  }

  async readNetworkCapture(options: { retainIncomplete?: boolean } = {}): Promise<unknown[]> {
    // A draining read awaits all in-flight body fetches so entries are fully
    // populated. A retaining read must not block on them: a slow or stalled
    // fetch would hold the caller past its deadline instead of returning the
    // current snapshot while the entry stays retained for a later read.
    if (!options.retainIncomplete && this._pendingBodyFetches.size > 0) {
      await Promise.all([...this._pendingBodyFetches]);
    }
    const entries = this._networkEntries.map(entry => ({ ...entry }));
    if (!options.retainIncomplete) {
      this._networkEntries = [];
      this._pendingRequests.clear();
      return entries;
    }
    const retained: typeof this._networkEntries = [];
    const reindexed = new Map<number, number>();
    this._networkEntries.forEach((entry, index) => {
      if (!entry.captureComplete) {
        reindexed.set(index, retained.length);
        retained.push(entry);
      }
    });
    this._networkEntries = retained;
    this._pendingRequests = new Map([...this._pendingRequests].flatMap(([id, index]) =>
      reindexed.has(index) ? [[id, reindexed.get(index)!]] : []));
    return entries;
  }

  async consoleMessages(level: string = 'all'): Promise<Array<{ type: string; text: string; timestamp: number }>> {
    if (!this._consoleCapturing) {
      await this.bridge.send('Runtime.enable');
      this.bridge.on('Runtime.consoleAPICalled', (params: unknown) => {
        const p = params as { type: string; args: Array<{ value?: unknown; description?: string }>; timestamp: number };
        const text = (p.args || []).map(a => a.value !== undefined ? String(a.value) : (a.description || '')).join(' ');
        this._consoleMessages.push({ type: p.type, text, timestamp: Date.now() });
        if (this._consoleMessages.length > 500) this._consoleMessages.shift();
      });
      // Capture uncaught exceptions as error-level messages
      this.bridge.on('Runtime.exceptionThrown', (params: unknown) => {
        const p = params as { timestamp: number; exceptionDetails?: { exception?: { description?: string }; text?: string } };
        const desc = p.exceptionDetails?.exception?.description || p.exceptionDetails?.text || 'Unknown exception';
        this._consoleMessages.push({ type: 'error', text: desc, timestamp: Date.now() });
        if (this._consoleMessages.length > 500) this._consoleMessages.shift();
      });
      this._consoleCapturing = true;
    }
    if (level === 'all') return [...this._consoleMessages];
    // 'error' level includes both console.error() and uncaught exceptions
    if (level === 'error') return this._consoleMessages.filter(m => m.type === 'error');
    return this._consoleMessages.filter(m => m.type === level);
  }

  async tabs(): Promise<unknown[]> {
    return [];
  }

  async selectTab(_target: number | string): Promise<void> {
    // Not supported in direct CDP mode
  }

  async cdp(method: string, params: Record<string, unknown> = {}): Promise<unknown> {
    return this.bridge.send(method, params);
  }

  async insertText(text: string): Promise<void> {
    await this.nativeType(text);
  }
}

function isCookie(value: unknown): value is BrowserCookie {
  return isRecord(value)
    && typeof value.name === 'string'
    && typeof value.value === 'string'
    && typeof value.domain === 'string';
}

function matchesCookieDomain(cookieDomain: string, targetDomain: string): boolean {
  const normalizedCookieDomain = cookieDomain.replace(/^\./, '').toLowerCase();
  const normalizedTargetDomain = targetDomain.replace(/^\./, '').toLowerCase();
  return normalizedTargetDomain === normalizedCookieDomain
    || normalizedCookieDomain.endsWith(`.${normalizedTargetDomain}`);
}

function selectCDPTarget(targets: CDPTarget[]): CDPTarget | undefined {
  const preferredPattern = compilePreferredPattern(process.env.OPENCLI_CDP_TARGET);
  return targets
    .map((target, index) => ({ target, index, score: scoreCDPTarget(target, preferredPattern) }))
    .filter(({ score }) => Number.isFinite(score))
    .sort((a, b) => b.score - a.score || a.index - b.index)[0]?.target;
}

function scoreCDPTarget(target: CDPTarget, preferredPattern?: RegExp): number {
  if (!target.webSocketDebuggerUrl) return Number.NEGATIVE_INFINITY;

  const type = (target.type ?? '').toLowerCase();
  const url = (target.url ?? '').toLowerCase();
  const title = (target.title ?? '').toLowerCase();
  const haystack = `${title} ${url}`;

  if (!haystack.trim() && !type) return Number.NEGATIVE_INFINITY;
  if (haystack.includes('devtools')) return Number.NEGATIVE_INFINITY;
  // Chrome exposes browser UI targets (e.g. the toolbar) alongside real tabs.
  // They cannot be navigated and must never outrank an about:blank page.
  if (/^chrome(?:-untrusted)?:\/\/[^/]*\.top-chrome(?:\/|$)/.test(url)) return Number.NEGATIVE_INFINITY;
  if (type === 'background_page' || type === 'service_worker') return Number.NEGATIVE_INFINITY;

  let score = 0;

  if (preferredPattern && preferredPattern.test(haystack)) score += 1000;

  if (type === 'page') score += 80;
  else if (type === 'iframe') score += 20;

  if (url.startsWith('about:blank')) score -= 120;
  if (url === '' || url === 'about:blank') score -= 40;

  if (title && title !== 'devtools') score += 25;

  return score;
}

function compilePreferredPattern(raw: string | undefined): RegExp | undefined {
  const value = raw?.trim();
  if (!value) return undefined;
  return new RegExp(escapeRegExp(value.toLowerCase()));
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export const __test__ = {
  selectCDPTarget,
  scoreCDPTarget,
};

function fetchJsonDirect(url: string): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const request = (parsed.protocol === 'https:' ? httpsRequest : httpRequest)(parsed, (res) => {
      const statusCode = res.statusCode ?? 0;
      if (statusCode < 200 || statusCode >= 300) {
        res.resume();
        reject(new Error(`Failed to fetch CDP targets: HTTP ${statusCode}`));
        return;
      }

      const chunks: Buffer[] = [];
      res.on('data', (chunk) => chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
      res.on('end', () => {
        try {
          resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
        } catch (error) {
          reject(error instanceof Error ? error : new Error(String(error)));
        }
      });
    });

    request.on('error', reject);
    request.setTimeout(10_000, () => request.destroy(new Error('Timed out fetching CDP targets')));
    request.end();
  });
}

