import { describe, expect, it, vi } from 'vitest';
import { getRegistry } from '@jackwener/opencli/registry';
import { AuthRequiredError, CommandExecutionError } from '@jackwener/opencli/errors';
import { requireJikeIdentity } from './utils.js';
import './auth.js';
import './feed.js';
import './notifications.js';
import './search.js';

function makePage(...evaluateResults) {
  return {
    goto: vi.fn().mockResolvedValue(undefined),
    wait: vi.fn().mockResolvedValue(undefined),
    autoScroll: vi.fn().mockResolvedValue(undefined),
    evaluate: vi.fn().mockImplementation(async () => evaluateResults.shift()),
  };
}

const identity = {
  ok: true,
  user_id: 'user-1',
  screen_name: 'Alice',
  username: 'alice',
};

describe('Jike identity guard', () => {
  it('preserves the whoami identity contract', async () => {
    const page = makePage(identity);

    await expect(getRegistry().get('jike/whoami').func(page, {})).resolves.toEqual({
      logged_in: true,
      site: 'jike',
      user_id: 'user-1',
      screen_name: 'Alice',
      username: 'alice',
    });
    expect(page.goto).toHaveBeenCalledWith('https://web.okjike.com/');
  });

  it('keeps login polling after a transient non-auth probe failure', async () => {
    const page = makePage(
      { kind: 'auth', detail: 'anonymous' },
      { kind: 'http', httpStatus: 503 },
      identity,
    );

    await expect(getRegistry().get('jike/login').func(page, { timeout: 5 })).resolves.toEqual({
      status: 'login_complete',
      logged_in: true,
      site: 'jike',
      user_id: 'user-1',
      screen_name: 'Alice',
      username: 'alice',
    });
    expect(page.goto).toHaveBeenNthCalledWith(1, 'https://web.okjike.com/');
    expect(page.goto).toHaveBeenNthCalledWith(2, 'https://web.okjike.com/login');
    expect(page.evaluate).toHaveBeenCalledTimes(3);
  });

  it('classifies missing or rejected credentials as AuthRequiredError', async () => {
    await expect(requireJikeIdentity(makePage({
      kind: 'auth',
      detail: 'Jike JK_ACCESS_TOKEN missing from localStorage (anonymous)',
    }))).rejects.toBeInstanceOf(AuthRequiredError);
  });

  it.each([
    [{ kind: 'http', httpStatus: 503 }],
    [{ kind: 'exception', detail: 'network failed' }],
    [{ unexpected: true }],
  ])('classifies non-auth probe failure as CommandExecutionError', async (probe) => {
    await expect(requireJikeIdentity(makePage(probe))).rejects.toBeInstanceOf(CommandExecutionError);
  });

  it.each([
    ['jike/feed', {}, 'https://web.okjike.com'],
    ['jike/search', { query: 'OpenCLI' }, 'https://web.okjike.com/search?q=OpenCLI'],
    ['jike/notifications', {}, 'https://web.okjike.com/notification'],
  ])('prevents %s from silently returning an empty anonymous result', async (commandName, args, expectedUrl) => {
    const page = makePage({
      kind: 'auth',
      detail: 'Jike JK_ACCESS_TOKEN missing from localStorage (anonymous)',
    });

    await expect(getRegistry().get(commandName).func(page, args)).rejects.toBeInstanceOf(AuthRequiredError);
    expect(page.goto).toHaveBeenCalledWith(expectedUrl);
    expect(page.evaluate).toHaveBeenCalledTimes(1);
  });

  it('continues feed extraction after a successful identity probe', async () => {
    const rows = [{ id: 'post-1', author: 'Alice', content: 'hello', likes: 2, comments: 1, time: 'now', url: 'https://web.okjike.com/originalPost/post-1' }];
    const page = makePage(identity, rows);

    await expect(getRegistry().get('jike/feed').func(page, { limit: 1 })).resolves.toEqual(rows);
    expect(page.evaluate).toHaveBeenCalledTimes(2);
  });

  it('continues notification extraction after a successful identity probe', async () => {
    const page = makePage(identity, {
      kind: 'response',
      status: 200,
      body: {
        data: [{
          id: 'notification-1',
          type: 'LIKE_PERSONAL_UPDATE',
          createdAt: 'now',
          actionItem: { users: [{ screenName: 'Bob' }], content: 'hello\nworld' },
        }],
      },
    });

    await expect(getRegistry().get('jike/notifications').func(page, { limit: 1 })).resolves.toEqual([{
      type: '赞了你的动态',
      user: 'Bob',
      content: 'hello world',
      time: 'now',
    }]);
    expect(page.evaluate).toHaveBeenCalledTimes(2);
  });
});

import { getRegistry } from '@jackwener/opencli/registry';
import { JSDOM } from 'jsdom';
import { describe, expect, it, vi } from 'vitest';
import { IDENTITY_PROBE_JS } from './auth.js';

function runIdentityProbe(html, url = 'https://www.1point3acres.com/bbs/') {
  const dom = new JSDOM(html, { url, runScripts: 'outside-only' });
  try { return dom.window.eval(IDENTITY_PROBE_JS); } finally { dom.window.close(); }
}

describe('1point3acres auth identity probe', () => {
  it('detects the current Discuz user-panel identity link', () => {
    const result = runIdentityProbe(`
      <div id="um">
        <a href="space-uid-123456.html" title="访问我的空间">test_user</a>
      </div>
    `);

    expect(result).toEqual({ ok: true, user_id: '123456', username: 'test_user' });
  });

  it('keeps legacy identity selectors as fallbacks', () => {
    const result = runIdentityProbe(`
      <div id="um">
        <div class="vwmy"><h4><a href="home.php?mod=space&uid=42">legacy_user</a></h4></div>
      </div>
    `);

    expect(result).toEqual({ ok: true, user_id: '42', username: 'legacy_user' });
  });

  it('does not report a successful blank identity when only logged-in menu ids render', () => {
    const result = runIdentityProbe('<div id="g_upmine"></div><div id="extcreditmenu"></div>');

    expect(result).toMatchObject({
      kind: 'shape',
      detail: '1point3acres bbs rendered logged-in menus but no identity link',
    });
  });

  it('treats an anonymous login link as auth required', () => {
    const result = runIdentityProbe('<a href="https://auth.1point3acres.com/login">登录</a>');

    expect(result).toMatchObject({ kind: 'auth' });
  });
});


describe('1point3acres whoami navigation and identity boundaries', () => {
  function pageFor(html, cookies = [{ name: 'discuz_auth', value: 'fixture' }]) {
    const dom = new JSDOM('', { url: 'https://www.1point3acres.com/', runScripts: 'outside-only' });
    const page = {
      getCookies: vi.fn(async () => cookies),
      wait: vi.fn(async () => {}),
      goto: vi.fn(async (url) => {
        dom.reconfigure({ url });
        dom.window.document.body.innerHTML = url === 'https://www.1point3acres.com/bbs/home.php?mod=space' ? html : '<main>SPA home</main>';
      }),
      evaluate: vi.fn(async (script) => dom.window.eval(script)),
    };
    return { dom, page };
  }

  it('reads the current-user panel from the Discuz-native page', async () => {
    const { dom, page } = pageFor('<div id="um"><a title="访问我的空间" href="space-uid-42.html">viewer</a></div>');
    try {
      await expect(getRegistry().get('1point3acres/whoami').func(page, {})).resolves.toMatchObject({ logged_in: true, user_id: '42', username: 'viewer' });
      expect(page.goto).toHaveBeenCalledExactlyOnceWith('https://www.1point3acres.com/bbs/home.php?mod=space');
    } finally { dom.window.close(); }
  });

  it.each([
    '<main>SPA home</main>',
    '<script id="__NEXT_DATA__">{}</script><img src="https://avatar.1p3a.com/000/12/34/56_avatar_middle.jpg">',
  ])('keeps missing self identity unknown even with an auth cookie', async (html) => {
    const { dom, page } = pageFor(html);
    try {
      await expect(getRegistry().get('1point3acres/whoami').func(page, {})).rejects.toMatchObject({ code: 'COMMAND_EXEC' });
    } finally { dom.window.close(); }
  });

  it('still reports an explicit login wall as AUTH_REQUIRED', async () => {
    const { dom, page } = pageFor('<a href="https://auth.1point3acres.com/login">登录</a>');
    try {
      await expect(getRegistry().get('1point3acres/whoami').func(page, {})).rejects.toMatchObject({ code: 'AUTH_REQUIRED' });
    } finally { dom.window.close(); }
  });

  it('rejects missing auth cookies before navigating', async () => {
    const { dom, page } = pageFor('', []);
    try {
      await expect(getRegistry().get('1point3acres/whoami').func(page, {})).rejects.toMatchObject({ code: 'AUTH_REQUIRED' });
      expect(page.goto).not.toHaveBeenCalled();
    } finally { dom.window.close(); }
  });
});

